def count_pairs(events):
    counts = {}
    for pair in events:
        counts[pair] = counts.get(pair, 0) + 1
    return counts

def unique_points(points):
    seen = set()
    result = []
    for p in points:
        key = tuple(p)
        if key not in seen:
            seen.add(key)
            result.append(key)
    return result

def neighbors(cell):
    r, c = cell
    return [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]

def render(cells, rows, cols):
    lines = []
    for r in range(rows):
        line = ""
        for c in range(cols):
            line += cells.get((r, c), ".")
        lines.append(line)
    return lines

